declare(strict_types=1);namespace BSPCompare;require __DIR__.'/_lib/site.php';use function BSPResearch\h;use function BSPResearch\j;
if(!in_array(parse_url($_SERVER['REQUEST_URI']??'',PHP_URL_PATH),[ROOT,ROOT.'index.php'],true)){http_response_code(404);exit('Not found');}$method=$_SERVER['REQUEST_METHOD']??'GET';if(!in_array($method,['GET','HEAD','POST'],true)){http_response_code(405);header('Allow: GET, HEAD, POST');exit('Method not allowed');}$id=$_GET['preset']??'light';if(!is_string($id)||!isset(presets()[$id]))$id='light';$plan=preset($id);$raw=json_encode($plan,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$error='';$r=null;try{if($method==='POST'){$raw=$_POST['recipe']??'';if(!is_string($raw))throw new \InvalidArgumentException('Recipe must be text.');$r=evaluate(\BSPResearch\decode($raw));$raw=json_encode($r['plan'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}else $r=evaluate($plan);}catch(\InvalidArgumentException|\JsonException $e){http_response_code(400);$error=$e->getMessage();if(!is_string($raw)||strlen($raw)>65536)$raw='';}catch(\Throwable $e){http_response_code(500);error_log('BSP comparison: '.$e->getMessage());$error='Calculation failed.';}
